CREATE TABLE assignment_configuration(id INTEGER PRIMARY KEY CHECK(id=1), strategy VARCHAR(20) NOT NULL CHECK(strategy IN ('SKILL','LOAD')));
INSERT INTO assignment_configuration VALUES (1,'SKILL');
CREATE TABLE technician_skills(user_id BIGINT REFERENCES technician_profiles(user_id), category_id BIGINT REFERENCES categories(id), proficiency INTEGER NOT NULL CHECK(proficiency BETWEEN 1 AND 3), PRIMARY KEY(user_id,category_id));
CREATE TABLE incidents(
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, version BIGINT NOT NULL DEFAULT 0,
 title VARCHAR(160) NOT NULL, description VARCHAR(8000) NOT NULL, reporter_id BIGINT NOT NULL REFERENCES user_accounts(id),
 service_id BIGINT NOT NULL REFERENCES it_services(id), category_id BIGINT NOT NULL REFERENCES categories(id),
 assignee_id BIGINT REFERENCES user_accounts(id), affected_users INTEGER NOT NULL CHECK(affected_users>0),
 impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 3), urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 3),
 criticality INTEGER NOT NULL CHECK(criticality BETWEEN 1 AND 3), priority VARCHAR(2) NOT NULL CHECK(priority IN ('P1','P2','P3','P4')),
 score INTEGER NOT NULL CHECK(score BETWEEN 1 AND 27),
 status VARCHAR(20) NOT NULL CHECK(status IN ('NEW','CLASSIFIED','ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','VERIFIED','CLOSED')),
 created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL,
 response_seconds INTEGER NOT NULL CHECK(response_seconds>0), resolution_seconds INTEGER NOT NULL CHECK(resolution_seconds>=response_seconds),
 response_due TIMESTAMPTZ NOT NULL, resolution_due TIMESTAMPTZ NOT NULL,
 acknowledged_at TIMESTAMPTZ, first_resolved_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ, closed_at TIMESTAMPTZ,
 cycle INTEGER NOT NULL DEFAULT 1 CHECK(cycle>0), cycle_started_at TIMESTAMPTZ NOT NULL,
 resolution_draft VARCHAR(8000) NOT NULL DEFAULT ''
);
CREATE INDEX incidents_reporter_idx ON incidents(reporter_id,created_at DESC);
CREATE INDEX incidents_assignee_idx ON incidents(assignee_id,status);
CREATE INDEX incidents_filter_idx ON incidents(status,priority,category_id,service_id);
CREATE INDEX incidents_created_idx ON incidents(created_at DESC);
CREATE TABLE incident_messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), author_id BIGINT NOT NULL REFERENCES user_accounts(id), kind VARCHAR(20) NOT NULL CHECK(kind IN ('PUBLIC','INTERNAL','REQUEST')), body VARCHAR(4000) NOT NULL, response_to BIGINT REFERENCES incident_messages(id), created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE resolution_cycles(incident_id BIGINT REFERENCES incidents(id), cycle INTEGER NOT NULL, started_at TIMESTAMPTZ NOT NULL, deadline TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ, PRIMARY KEY(incident_id,cycle));
CREATE TABLE resolutions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), cycle INTEGER NOT NULL, technician_id BIGINT NOT NULL REFERENCES user_accounts(id), details VARCHAR(8000) NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(incident_id,cycle));
CREATE TABLE feedback(incident_id BIGINT PRIMARY KEY REFERENCES incidents(id), reporter_id BIGINT NOT NULL REFERENCES user_accounts(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), comment VARCHAR(2000) NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE sla_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), cycle INTEGER NOT NULL, kind VARCHAR(30) NOT NULL CHECK(kind IN ('RESPONSE_WARNING','RESPONSE_BREACH','RESOLUTION_WARNING','RESOLUTION_BREACH')), deadline TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(incident_id,cycle,kind));
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES user_accounts(id), incident_id BIGINT REFERENCES incidents(id), channel VARCHAR(20) NOT NULL CHECK(channel IN ('IN_APP','SIMULATED_EMAIL')), subject VARCHAR(200) NOT NULL, body VARCHAR(2000) NOT NULL, delivery_status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ NOT NULL, read_at TIMESTAMPTZ);
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
ALTER TABLE audit_entries ADD COLUMN incident_id BIGINT REFERENCES incidents(id);
ALTER TABLE audit_entries ADD COLUMN previous_state VARCHAR(40);
ALTER TABLE audit_entries ADD COLUMN new_state VARCHAR(40);
CREATE INDEX audit_incident_idx ON audit_entries(incident_id,id);
CREATE TABLE ai_suggestions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents(id), incident_version BIGINT NOT NULL, requested_by BIGINT NOT NULL REFERENCES user_accounts(id), kind VARCHAR(20) NOT NULL CHECK(kind IN ('CATEGORY','RESOLUTION')), category_id BIGINT REFERENCES categories(id), content VARCHAR(8000) NOT NULL, model VARCHAR(200) NOT NULL, created_at TIMESTAMPTZ NOT NULL, applied_at TIMESTAMPTZ);
